// Chown family system calls (often provided by glibc wrappers)

// Change owner/group of file specified by path (follows symlinks)
int chown(const char *pathname, uid_t owner, gid_t group);

// Change owner/group of symlink itself (does not follow)
int lchown(const char *pathname, uid_t owner, gid_t group);

// Change owner/group of open file descriptor
int fchown(int fd, uid_t owner, gid_t group);

// Example usage: set owner to 1000, keep existing group (-1)
int status = chown("/mnt/file", 1000, (gid_t)-1);

// fchownat: Change owner/group using relative paths and flags
// Use AT_SYMLINK_NOFOLLOW to mimic lchown() behavior
int fchownat(int dirfd, const char *pathname,
             uid_t owner, gid_t group, int flags);

// Example: Change owner of relative path (no symlink follow)
fchownat(dirfd, "temp/link", 400, 400, AT_SYMLINK_NOFOLLOW);
